@using sv_bfe1be72384d4570af5b94da6779f10f.Models

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => OnStepClicked(stepIndex)">
            <div class="step-circle">
                @if (CompletedSteps.Contains(stepIndex))
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (stepIndex < StepNames.Count - 1)
        {
            <div class="step-connector @(CompletedSteps.Contains(stepIndex) ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnNavigateToStep { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task OnStepClicked(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnNavigateToStep.InvokeAsync(step);
        }
    }
}

@using sv_bfe1be72384d4570af5b94da6779f10f.Models

<div class="step-content">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" class="form-control" value="@FullName"
               @onchange="e => FullName = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" class="form-control" value="@Email"
               @onchange="e => Email = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" class="form-control" value="@Phone"
               @onchange="e => Phone = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" class="form-control" value="@Address"
               @onchange="e => Address = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="step-buttons">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo? Info { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string FullName { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;
    private string Address { get; set; } = string.Empty;
    private string ErrorMessage { get; set; } = string.Empty;
    private bool IsValidating { get; set; }

    protected override void OnParametersSet()
    {
        if (Info is not null)
        {
            FullName = Info.FullName;
            Email = Info.Email;
            Phone = Info.Phone;
            Address = Info.Address;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            if (ValidateEmail is not null)
            {
                var isValid = await ValidateEmail(Email);
                if (!isValid)
                {
                    ErrorMessage = "Please enter a valid email address.";
                    return;
                }
            }

            await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@using sv_bfe1be72384d4570af5b94da6779f10f.Models

<div class="work-entry-form">
    <div class="entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (CanRemove)
        {
            <button class="btn btn-sm btn-danger" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" class="form-control" value="@Entry.Company"
               @onchange="e => UpdateEntry(company: e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" class="form-control" value="@Entry.Title"
               @onchange="e => UpdateEntry(title: e.Value?.ToString())" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(startDate: DateTime.TryParse(e.Value?.ToString(), out var d) ? d : Entry.StartDate)" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(endDate: DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null)" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(description: e.Value?.ToString())"></textarea>
    </div>
</div>

@code {
    [Parameter] public WorkEntry Entry { get; set; } = new("", "", DateTime.Today, null, "");
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && !string.IsNullOrEmpty(Entry.Company);

    private void UpdateEntry(string? company = null, string? title = null,
        DateTime? startDate = null, DateTime? endDate = null, string? description = null)
    {
        var updated = Entry with
        {
            Company = company ?? Entry.Company,
            Title = title ?? Entry.Title,
            StartDate = startDate ?? Entry.StartDate,
            EndDate = endDate ?? Entry.EndDate,
            Description = description ?? Entry.Description
        };
        OnEntryChanged.InvokeAsync(updated);
    }

    private void HandleCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { EndDate = isCurrent ? null : DateTime.Today };
        OnEntryChanged.InvokeAsync(updated);
    }
}

@using sv_bfe1be72384d4570af5b94da6779f10f.Models

<div class="step-content">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       CanRemove="Entries.Count > 1"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-buttons">
        <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntry> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string ErrorMessage { get; set; } = string.Empty;

    protected override void OnParametersSet()
    {
        if (Entries.Count == 0)
        {
            Entries = new List<WorkEntry> { new("", "", DateTime.Today, null, "") };
        }
    }

    private void UpdateEntry(int index, WorkEntry updated)
    {
        Entries[index] = updated;
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private async Task HandleNext()
    {
        ErrorMessage = string.Empty;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(new List<WorkEntry>(Entries));
    }
}

