@using sv_bfe1be72384d4570af5b94da6779f10f.Models

<div class="reference-form">
    <div class="entry-header">
        <h5>Reference @(Index + 1)</h5>
        @if (CanRemove)
        {
            <button class="btn btn-sm btn-danger" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" class="form-control" value="@Ref.Name"
               @onchange="e => UpdateRef(name: e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" class="form-control" value="@Ref.Relationship"
               @onchange="e => UpdateRef(relationship: e.Value?.ToString())" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" class="form-control" value="@Ref.Email"
                   @onchange="e => UpdateRef(email: e.Value?.ToString())" />
        </div>

        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" class="form-control" value="@Ref.Phone"
                   @onchange="e => UpdateRef(phone: e.Value?.ToString())" />
        </div>
    </div>
</div>

@code {
    [Parameter] public Reference Ref { get; set; } = new("", "", "", "");
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnRefChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void UpdateRef(string? name = null, string? relationship = null,
        string? email = null, string? phone = null)
    {
        var updated = Ref with
        {
            Name = name ?? Ref.Name,
            Relationship = relationship ?? Ref.Relationship,
            Email = email ?? Ref.Email,
            Phone = phone ?? Ref.Phone
        };
        OnRefChanged.InvokeAsync(updated);
    }
}

@using sv_bfe1be72384d4570af5b94da6779f10f.Models

<div class="step-content">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Ref="References[index]"
                       Index="index"
                       CanRemove="References.Count > 2"
                       OnRefChanged="e => UpdateReference(index, e)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-buttons">
        <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string ErrorMessage { get; set; } = string.Empty;

    protected override void OnParametersSet()
    {
        if (References.Count == 0)
        {
            References = new List<Reference>
            {
                new("", "", "", ""),
                new("", "", "", "")
            };
        }
    }

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference("", "", "", ""));
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = string.Empty;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(new List<Reference>(References));
    }
}

