    background: white;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h3 {
    margin-bottom: 1.5rem;
    color: #212529;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    color: #495057;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
    transition: border-color 0.15s;
}

.form-control:focus {
    outline: none;
    border-color: #86b7fe;
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.5rem;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #dee2e6;
}

.btn {
    padding: 0.5rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    border: 1px solid transparent;
    transition: all 0.15s;
}

.btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-outline-secondary {
    background: white;
    color: #6c757d;
    border-color: #6c757d;
}

.btn-outline-secondary:hover {
    background: #6c757d;
    color: white;
}

.btn-secondary {
    background: #6c757d;
    color: white;
    border-color: #6c757d;
}

.btn-success {
    background: #198754;
    color: white;
    border-color: #198754;
}

.btn-success:hover:not(:disabled) {
    background: #157347;
}

.btn-danger {
    background: #dc3545;
    color: white;
    border-color: #dc3545;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.875rem;
}

.btn-lg {
    padding: 0.75rem 2rem;
    font-size: 1.125rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    text-decoration: underline;
    padding: 0;
    cursor: pointer;
}

/* Alerts */
.alert {
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

.alert-danger {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.alert-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

/* Work Entry & Reference Forms */
.work-entry-form,
.reference-form {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h5 {
    margin: 0;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 250px;
    resize: vertical;
}

.character-count {
    text-align: right;
    font-size: 0.875rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.character-count.over-limit {
    color: #dc3545;
    font-weight: bold;
}

/* Review Step */
.review-section {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h4 {
    margin: 0;
    font-size: 1.1rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    color: #6c757d;
    font-weight: 500;
}

.review-section dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #e9ecef;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    max-height: 200px;
    overflow-y: auto;
}

.submission-confirmation {
    text-align: center;
    padding: 2rem;
}

.submission-confirmation h4 {
    color: #198754;
    margin-bottom: 1rem;
}

